        R = rets.tail(win).to_numpy(dtype=float)
        M = mkt.tail(win).to_numpy(dtype=float)
        mask = np.isfinite(R) & np.isfinite(M)[:, None]
        nobs = mask.sum(axis=0)
        Rv = np.where(mask, R, np.nan)
        Mv = np.where(mask, M[:, None], np.nan)
        with np.errstate(all='ignore'):
            mR = np.nanmean(Rv, axis=0)
            mM = np.nanmean(Mv, axis=0)
            cov = np.nansum((Rv - mR) * (Mv - mM), axis=0) / np.maximum(nobs - 1, 1)
            var = np.nansum((Mv - mM) ** 2, axis=0) / np.maximum(nobs - 1, 1)
            beta_vals = cov / var
        beta_vals = np.where(np.isfinite(beta_vals) & (nobs >= 40), beta_vals, 1.0)
        beta = pd.Series(beta_vals, index=tickers)
    else:
        beta = pd.Series(1.0, index=tickers)

    vol60 = rets.tail(60).std(ddof=0) * math.sqrt(252.0)
    vol60 = vol60.replace([np.inf, -np.inf], np.nan).clip(lower=0.05, upper=2.0)
    valid = valid & vol60.notna() & (vol60 > 0)

    def lag_ret(lag):
        if p.shape[0] > lag:
            return p.iloc[-1] / p.iloc[-1 - lag] - 1.0
        return pd.Series(np.nan, index=tickers)

    r12 = lag_ret(252)
    r6 = lag_ret(126)

    if p.shape[0] > 253:
        mom12 = p.iloc[-22] / p.iloc[-253] - 1.0
    elif p.shape[0] > 127:
        mom12 = p.iloc[-22] / p.iloc[-127] - 1.0
    else:
        mom12 = r12

    if p.shape[0] > 127:
        mom6 = p.iloc[-22] / p.iloc[-127] - 1.0
    elif p.shape[0] > 64:
        mom6 = p.iloc[-22] / p.iloc[-64] - 1.0
    else:
        mom6 = r6

    def mkt_cum(start, end):
        if len(mkt) >= abs(start):
            arr = mkt.iloc[start:end].to_numpy(dtype=float)
            arr = arr[np.isfinite(arr)]
            if len(arr) > 0:
                return float(np.expm1(np.nansum(np.log1p(arr))))
        return 0.0

    if p.shape[0] > 253:
        mc12 = mkt_cum(-252, -21)
        resid12 = mom12 - beta * mc12
    else:
        resid12 = mom12

    if p.shape[0] > 127:
        mc6 = mkt_cum(-126, -21)
        resid6 = mom6 - beta * mc6
    else:
        resid6 = mom6

    mom12_adj = mom12 / vol60
    resid12_adj = resid12 / vol60
    mom6_adj = mom6 / vol60

    score = (0.50 * _zscore(mom12_adj)
             + 0.30 * _zscore(resid12_adj)
             + 0.20 * _zscore(mom6_adj)
             - 0.10 * _zscore(vol60))
    score = score.replace([np.inf, -np.inf], np.nan)
    valid = valid & score.notna() & np.isfinite(score)

    if valid.sum() < 8:
        alt = mom12.where(valid & mom12.notna())
        if alt.notna().sum() < 8:
            return zero
        score = _zscore(alt)
        valid = alt.notna() & np.isfinite(score)

    beta_valid = beta[valid]
    if beta_valid.notna().sum() < 8:
        return zero
    qs = np.nanpercentile(beta_valid, [20, 40, 60, 80])
    bucket = np.digitize(beta.to_numpy(dtype=float), qs)

    longs = []
    shorts = []
    for b in range(5):
        idx = valid & (bucket == b) & score.notna()
        if idx.sum() < 2:
            continue
        s = score[idx].sort_values()
        k = min(5, len(s) // 2)
        if k < 1:
            continue
        longs.extend(s.index[-k:].tolist())
        shorts.extend(s.index[:k].tolist())

    n_side = min(len(longs), len(shorts), 25)
    if n_side < 1:
        return zero
    longs = longs[:n_side]
    shorts = shorts[:n_side]

    if len(mkt.dropna()) >= 60:
        mvol = float(mkt.tail(60).std(ddof=0) * math.sqrt(252.0))
    else:
        mvol = 0.20
    if not np.isfinite(mvol) or mvol <= 0:
        mvol = 0.20
    scale = min(1.0, max(0.35, 0.20 / mvol))
    side_gross = 0.5 * scale
    w = min(0.02, side_gross / float(n_side))

    weights = pd.Series(0.0, index=tickers, dtype=float)
    weights.loc[longs] = w
    weights.loc[shorts] = -w

    net = weights.sum()
    if abs(net) > 1e-12:
        nz = weights.index[weights != 0.0]
        if len(nz) > 0:
            weights.loc[nz] -= net / len(nz)

    weights = weights.replace([np.inf, -np.inf], 0.0).fillna(0.0).clip(-0.02, 0.02)
    gross = weights.abs().sum()
    if gross > 1.0:
        weights = weights * (1.0 / gross)
    net = weights.sum()
    if abs(net) > 1e-12:
        nz = weights.index[weights != 0.0]
        if len(nz) > 0:
            weights.loc[nz] -= net / len(nz)

    return weights.clip(-0.02, 0.02).fillna(0.0).astype(float)

import numpy as np
import pandas as pd

def generate_weights(history, universe):
    universe = pd.Index(universe)
    n = len(universe)
    if n == 0:
        return pd.Series(dtype=float)

    ac = history.get('adjusted_close')
    if ac is None:
        ac = history.get('close')
    if ac is None:
        return pd.Series(0.0, index=universe)

    cols = [t for t in universe if t in ac.columns]
    if len(cols) < 2:
        return pd.Series(0.0, index=universe)

    prices = ac.loc[:, cols].tail(300).astype(float).copy()
    if len(prices) < 25:
        return pd.Series(0.0, index=universe)

    rets = prices.pct_change(fill_method=None)
    last = prices.iloc[-1]
    vol = rets.tail(60).std(ddof=0)

    if len(prices) >= 22:
        r21 = prices.iloc[-1] / prices.iloc[-22] - 1.0
    else:
        r21 = pd.Series(np.nan, index=cols)

    if len(prices) >= 252:
        mom = prices.iloc[-22] / prices.iloc[-252] - 1.0
    elif len(prices) >= 126:
        mom = prices.iloc[-22] / prices.iloc[-126] - 1.0
    else:
        mom = pd.Series(np.nan, index=cols)

    vol_df = history.get('volume')
    if vol_df is not None:
        vcols = [t for t in cols if t in vol_df.columns]
        v = vol_df.loc[:, vcols].tail(20).astype(float)
        close_df = history.get('close')
        if close_df is not None:
            c = close_df.loc[:, vcols].tail(20).astype(float)
        else:
            c = prices.loc[:, vcols].tail(20)
        adv = (v * c).mean(skipna=True)
        adv = adv.reindex(cols)
    else:
        adv = pd.Series(np.nan, index=cols)

    eligible_df = history.get('eligible')
    if eligible_df is not None and len(eligible_df):
        erow = eligible_df.iloc[-1].reindex(cols)
        elig = erow.fillna(False).astype(bool)
    else:
        elig = pd.Series(True, index=cols)

    df = pd.DataFrame({'r21': r21, 'mom': mom, 'vol': vol, 'adv': adv, 'eligible': elig, 'last': last})
    df = df.replace([np.inf, -np.inf], np.nan)
    df = df[df['eligible'] & df['last'].notna() & df['r21'].notna() & df['vol'].notna() & (df['vol'] > 0)]

    if df['adv'].notna().sum() >= 5:
        df = df[df['adv'].notna() & (df['adv'] > 0)]
        if len(df) >= 5:
            q = df['adv'].quantile(0.20)
            df = df[df['adv'] >= q]

    if len(df) < 4:
        return pd.Series(0.0, index=universe)

    rank_rev = (-df['r21']).rank(method='average', pct=True)
    rank_mom = df['mom'].rank(method='average', pct=True).fillna(0.5)
    rank_lowvol = (-df['vol']).rank(method='average', pct=True)

    df = df.copy()
    df['score'] = 0.55 * rank_rev + 0.30 * rank_mom + 0.15 * rank_lowvol

    n_side = min(50, len(df) // 2)
    if n_side < 1:
        return pd.Series(0.0, index=universe)

    ordered = df.sort_values('score', ascending=False)
    longs = ordered.index[:n_side]
    shorts = ordered.index[-n_side:]

    side_gross = min(0.5, 0.02 * n_side)
    w = side_gross / n_side

    weights = pd.Series(0.0, index=universe)
    weights.loc[longs] = w
    weights.loc[shorts] = -w
    weights = weights.replace([np.inf, -np.inf], 0.0).fillna(0.0).clip(-0.02, 0.02)
    return weights.astype(float)

import math
import numpy as np
import pandas as pd


def _get_df(history, key, tickers):
    df = history.get(key)
    if df is None:
        return None
    try:
        return df.reindex(columns=tickers)
    except Exception:
        return None


def generate_weights(history, universe):
    tickers = pd.Index(list(universe))
    if len(tickers) == 0:
        return pd.Series(dtype=float)

    zero = pd.Series(0.0, index=tickers, dtype=float)

    ac = _get_df(history, 'adjusted_close', tickers)
    if ac is None or ac.dropna(how='all').empty:
        ac = _get_df(history, 'close', tickers)
    if ac is None or ac.empty:
        return zero

    ac = ac.tail(420)
    if len(ac) < 80:
        return zero

    dates = ac.index
    last_pos = len(dates) - 1

    signal_pos = last_pos
    try:
        periods = dates.to_period('M')
        cur = periods[-1]
        prior = np.where(periods < cur)[0]
        if len(prior) > 0:
            signal_pos = int(prior[-1])
    except Exception:
        signal_pos = last_pos

    if signal_pos < 60:
        signal_pos = last_pos

    price = ac.iloc[:signal_pos + 1].astype(float)
    if len(price) < 80:
        return zero

    last_sig = price.iloc[-1]
    latest_price = ac.iloc[-1].astype(float)

    elig_df = _get_df(history, 'eligible', tickers)
    if elig_df is not None and len(elig_df) > 0:
        try:
            e = elig_df.reindex(index=ac.index).iloc[-1]
            e = e.fillna(False).astype(bool)
        except Exception:
            e = pd.Series(True, index=tickers)
    else:
        e = pd.Series(True, index=tickers)

    cnt = price.notna().sum()
    valid = (
        latest_price.notna() & np.isfinite(latest_price) & (latest_price > 2.0)
        & last_sig.notna() & np.isfinite(last_sig) & (last_sig > 2.0)
        & (cnt >= 80) & e
    )

    raw = _get_df(history, 'close', tickers)
    if raw is None:
        raw = ac
    raw_sig = raw.reindex(index=ac.index).iloc[:signal_pos + 1].astype(float)

    vol_df = _get_df(history, 'volume', tickers)
    if vol_df is not None:
        v = vol_df.reindex(index=ac.index).iloc[:signal_pos + 1].tail(21).astype(float)
        c = raw_sig.tail(21)
        adv = (v * c).median()
        adv_ok = adv.notna() & np.isfinite(adv) & (adv > 0)
        if adv_ok.sum() >= 20:
            thresh = max(250000.0, float(adv[adv_ok].quantile(0.20)))
            valid = valid & adv_ok & (adv >= thresh)

    rets = price.pct_change(fill_method=None)
    vol60 = rets.tail(60).std(ddof=0).replace([np.inf, -np.inf], np.nan)
    valid = valid & vol60.notna() & (vol60 > 0.005)

    def form(k):
        if len(price) > k:
            return price.iloc[-1] / price.iloc[-1 - k] - 1.0
        return pd.Series(np.nan, index=tickers)

    r5 = form(5)
    r21 = form(21)
    r252 = form(252)

    if len(price) >= 252:
        mom = price.iloc[-22] / price.iloc[-252] - 1.0
    elif len(price) >= 126:
        mom = price.iloc[-22] / price.iloc[-126] - 1.0
    else:
        mom = r252

    max21 = rets.tail(21).max()

    daily = rets.tail(260)
    mkt_ret = daily.mean(axis=1, skipna=True).dropna()
    if len(mkt_ret) >= 60:
        mkt_level = (1.0 + mkt_ret).cumprod()
        if len(mkt_level) >= 200:
            trend_up = bool(mkt_level.iloc[-1] > mkt_level.tail(200).mean())
        else:
            trend_up = bool(mkt_level.iloc[-1] > mkt_level.mean())
        mvol = float(mkt_ret.tail(60).std(ddof=0) * math.sqrt(252.0))
        roll_vol = mkt_ret.rolling(60).std(ddof=0) * math.sqrt(252.0)
        rv = roll_vol.dropna()
        if len(rv) > 20:
            high_vol = bool(mvol > float(rv.quantile(0.75)))
        else:
            high_vol = bool(mvol > 0.20)
    else:
        trend_up = True
        high_vol = False

    rev_score = (-r21 / (vol60 * math.sqrt(21.0))).replace([np.inf, -np.inf], np.nan)
    mom_score = (mom / (vol60 * math.sqrt(252.0))).replace([np.inf, -np.inf], np.nan)
    lowvol_score = (-vol60).replace([np.inf, -np.inf], np.nan)
    max_score = (-max21).replace([np.inf, -np.inf], np.nan)

    r_rev = rev_score.where(valid).rank(method='average', pct=True).fillna(0.5)
    r_mom = mom_score.where(valid).rank(method='average', pct=True).fillna(0.5)
    r_low = lowvol_score.where(valid).rank(method='average', pct=True).fillna(0.5)
    r_max = max_score.where(valid).rank(method='average', pct=True).fillna(0.5)

    if trend_up and not high_vol:
        score = 0.45 * r_rev + 0.30 * r_mom + 0.15 * r_low + 0.10 * r_max
        gross_target = 1.0
    else:
        score = 0.20 * r_rev + 0.10 * r_mom + 0.50 * r_low + 0.20 * r_max
        gross_target = 0.60 if high_vol else 0.80

    score = score.where(valid).replace([np.inf, -np.inf], np.nan).dropna()
    if len(score) < 10:
        return zero

    n_side = min(25, len(score) // 2)
    if n_side < 5:
        return zero

    ordered = score.sort_values()
    shorts = ordered.index[:n_side]
    longs = ordered.index[-n_side:]

    w = min(0.02, 0.5 / float(n_side)) * gross_target

    weights = zero.copy()
    weights.loc[longs] = w
    weights.loc[shorts] = -w

    weights = weights.replace([np.inf, -np.inf], 0.0).fillna(0.0).clip(-0.02, 0.02)
    gross = float(weights.abs().sum())
    if gross > 1.0:
        weights = weights * (1.0 / gross)

    return weights.astype(float)

import numpy as np
import pandas as pd
import math

def _rank_pct(s):
    s = pd.to_numeric(s, errors='coerce')
    s = s.replace([np.inf, -np.inf], np.nan)
    if s.notna().sum() < 2:
        return pd.Series(0.5, index=s.index)
    return s.rank(method='average', pct=True)

def generate_weights(history, universe):
    tickers = pd.Index(list(universe))
    weights = pd.Series(0.0, index=tickers, dtype=float)
    if len(tickers) == 0:
        return weights

    adj = history.get('adjusted_close')
    raw = history.get('close')
    vol_df = history.get('volume')
    elig_df = history.get('eligible')

    if adj is None:
        adj = raw
    if adj is None or adj.empty:
        return weights
    try:
        adj = adj.reindex(columns=tickers)
    except Exception:
        return weights

    if raw is None:
        raw = adj
    else:
        try:
            raw = raw.reindex(columns=tickers)
        except Exception:
            raw = adj

    dates = adj.index
    if len(dates) < 70:
        return weights

    current = dates[-1]
    try:
        month_start = pd.Timestamp(year=current.year, month=current.month, day=1)
    except Exception:
        month_start = current
    prior = dates[dates < month_start]
    if len(prior) > 0:
        signal_date = prior[-1]
    else:
        signal_date = dates[-1]

    p_all = adj.loc[:signal_date]
    p = p_all.tail(320)
    if len(p) < 70:
        return weights

    r_all = raw.loc[:signal_date]
    r = r_all.reindex(index=p.index, columns=tickers)

    v = None
    if vol_df is not None:
        try:
            v = vol_df.reindex(columns=tickers).loc[:signal_date].reindex(index=p.index)
        except Exception:
            v = None

    last_adj = pd.to_numeric(p.iloc[-1], errors='coerce').astype(float)
    if r is not None and len(r) > 0:
        last_raw = pd.to_numeric(r.iloc[-1], errors='coerce').astype(float)
    else:
        last_raw = last_adj

    valid = last_adj.notna() & np.isfinite(last_adj) & (last_adj > 0.0)
    valid = valid & last_raw.notna() & np.isfinite(last_raw) & (last_raw > 2.0)

    cnt = p.notna().sum()
    valid = valid & (cnt >= min(120, max(50, len(p) // 2)))

    if elig_df is not None:
        try:
            e = elig_df.reindex(columns=tickers).loc[:signal_date]
            if len(e) > 0:
                el = e.iloc[-1].fillna(False).astype(bool)
                valid = valid & el
        except Exception:
            pass

    rets = p / p.shift(1) - 1.0
    vol = rets.tail(120).std(ddof=0) * math.sqrt(252.0)
    vol = pd.to_numeric(vol, errors='coerce').replace([np.inf, -np.inf], np.nan)
    vol = vol.clip(lower=0.05, upper=2.0)
    valid = valid & vol.notna() & np.isfinite(vol) & (vol > 0.0)

    if len(p) > 253:
        r12 = p.iloc[-22] / p.iloc[-253] - 1.0
    elif len(p) > 127:
        r12 = p.iloc[-22] / p.iloc[-127] - 1.0
    else:
        r12 = pd.Series(np.nan, index=tickers)

    if len(p) > 127:
        r6 = p.iloc[-22] / p.iloc[-127] - 1.0
    elif len(p) > 64:
        r6 = p.iloc[-22] / p.iloc[-64] - 1.0
    else:
        r6 = pd.Series(np.nan, index=tickers)

    r12a = r12 / vol
    r6a = r6 / vol

    rank12 = _rank_pct(r12a).fillna(0.5)
    rank6 = _rank_pct(r6a).fillna(0.5)
    rankvol = _rank_pct(-vol).fillna(0.5)

    score = 0.55 * rank12 + 0.30 * rank6 + 0.15 * rankvol

    if v is not None:
        try:
            adv = (r * v).tail(60).median()
            adv = pd.to_numeric(adv, errors='coerce').replace([np.inf, -np.inf], np.nan)
            if (valid & adv.notna()).sum() >= 20:
                q = adv[valid & adv.notna()].quantile(0.2)
                thr = max(5e5, float(q) if np.isfinite(q) else 0.0)
                valid = valid & adv.notna() & (adv >= thr)
        except Exception:
            pass

    valid = valid & score.notna() & np.isfinite(score)

    if valid.sum() < 6:
        valid = last_adj.notna() & np.isfinite(last_adj) & (last_adj > 0.0)
        valid = valid & last_raw.notna() & np.isfinite(last_raw) & (last_raw > 2.0)
        valid = valid & score.notna() & np.isfinite(score)

    if valid.sum() < 4:
        return weights

    s = score[valid].dropna().sort_values()
    n_side = min(30, len(s) // 2)
    if n_side < 1:
        return weights

    w = min(0.02, 0.5 / float(n_side))
    longs = s.index[-n_side:]
    shorts = s.index[:n_side]

    weights.loc[longs] = w
    weights.loc[shorts] = -w
    weights = weights.replace([np.inf, -np.inf], 0.0).fillna(0.0).clip(-0.02, 0.02)
    return weights.astype(float)

import numpy as np
import pandas as pd
import math


def _get_df(history, names):
    for name in names:
        obj = history.get(name) if isinstance(history, dict) else None
        if isinstance(obj, pd.DataFrame):
            return obj
    return None


def _zscore(s):
    s = pd.to_numeric(s, errors='coerce').replace([np.inf, -np.inf], np.nan)
    if s.notna().sum() < 2:
        return pd.Series(0.0, index=s.index)
    mu = s.mean()
    sd = s.std()
    if not np.isfinite(sd) or sd < 1e-12:
        return pd.Series(0.0, index=s.index)
    return ((s - mu) / sd).fillna(0.0)


def generate_weights(history, universe):
    tickers = pd.Index(list(universe))
    zero = pd.Series(0.0, index=tickers, dtype=float)
    if len(tickers) == 0:
        return zero

    price = _get_df(history, ['adjusted_close', 'close'])
    if price is None:
        return zero
    try:
        price = price.reindex(columns=tickers).astype(float)
    except Exception:
        return zero
    if price.shape[0] < 80:
        return zero

    last_pos = price.shape[0] - 1
    block = 21
    signal_pos = (last_pos // block) * block
    if signal_pos < 60:
        return zero

    last_close = price.iloc[last_pos]
    valid = last_close.notna() & np.isfinite(last_close) & (last_close > 2.0)
    counts = price.iloc[:last_pos + 1].notna().sum()
    valid = valid & (counts >= 60)

    elig = _get_df(history, ['eligible'])
    if elig is not None and len(elig.index) > 0:
        try:
            e = elig.reindex(columns=tickers).iloc[-1]
            valid = valid & e.fillna(False).astype(bool)
        except Exception:
            pass

    vol_df = _get_df(history, ['volume'])
    raw_close = _get_df(history, ['close'])
    if vol_df is not None:
        try:
            v = vol_df.reindex(columns=tickers).iloc[-20:].astype(float)
            if raw_close is not None:
                c = raw_close.reindex(columns=tickers).iloc[-20:].astype(float)
            else:
                c = price.iloc[-20:].astype(float)
            adv = (v * c).median()
            valid = valid & adv.notna() & np.isfinite(adv) & (adv > 250000.0)
        except Exception:
            pass

    p = price.iloc[:signal_pos + 1]
    if p.shape[0] < 61:
        return zero
    last_sig = p.iloc[-1]
    rets = p.pct_change(fill_method=None)

    def lag_ret(lag):
        if p.shape[0] > lag:
            return p.iloc[-1] / p.iloc[-1 - lag] - 1.0
        return pd.Series(np.nan, index=tickers)

    def between_ret(recent_lag, old_lag):
        if p.shape[0] > old_lag:
            return p.iloc[-1 - recent_lag] / p.iloc[-1 - old_lag] - 1.0
        return pd.Series(np.nan, index=tickers)

    r6 = lag_ret(126)
    r12 = lag_ret(252)
    mom12 = between_ret(21, 252) if p.shape[0] > 252 else pd.Series(np.nan, index=tickers)
    mom6 = between_ret(21, 126) if p.shape[0] > 126 else pd.Series(np.nan, index=tickers)
    mom = mom12.copy()
    mom = mom.where(mom.notna(), mom6)
    mom = mom.where(mom.notna(), r12)
    mom = mom.where(mom.notna(), r6)

    vol60 = rets.tail(60).std(ddof=0)
    vol60 = vol60.replace([np.inf, -np.inf], np.nan).clip(lower=0.005)
    ann_vol = vol60 * math.sqrt(252.0)

    mkt = rets.mean(axis=1)
    win = min(120, max(20, rets.shape[0] - 1))
    R = rets.tail(win).to_numpy(dtype=float)
    M = mkt.tail(win).to_numpy(dtype=float)
    if R.size == 0:
        beta = pd.Series(1.0, index=tickers)
    else:
        mask = np.isfinite(R) & np.isfinite(M)[:, None]
        nobs = mask.sum(axis=0)
        Rv = np.where(mask, R, np.nan)
        Mv = np.where(mask, M[:, None], np.nan)
        with np.errstate(all='ignore'):
            mR = np.nanmean(Rv, axis=0)
            mM = np.nanmean(Mv, axis=0)
            cov = np.nansum((Rv - mR) * (Mv - mM), axis=0) / np.maximum(nobs - 1, 1)
            var = np.nansum((Mv - mM) ** 2, axis=0) / np.maximum(nobs - 1, 1)
            beta_vals = cov / var
        beta_vals = np.where(np.isfinite(beta_vals) & (nobs >= 40), beta_vals, 1.0)
        beta = pd.Series(beta_vals, index=tickers)

    if p.shape[0] > 252 and rets.shape[0] >= 252:
        mkt_cum = float(np.expm1(np.nansum(np.log1p(mkt.iloc[-252:-21].to_numpy(dtype=float)))))
        resid = mom12 - beta * mkt_cum
        resid = resid.where(resid.notna(), mom - beta * mkt_cum)
    elif p.shape[0] > 126 and rets.shape[0] >= 126:
        mkt_cum = float(np.expm1(np.nansum(np.log1p(mkt.iloc[-126:-21].to_numpy(dtype=float)))))
        resid = mom6 - beta * mkt_cum
        resid = resid.where(resid.notna(), mom - beta * mkt_cum)
    else:
        resid = mom

    mom_adj = mom / ann_vol
    resid_adj = resid / ann_vol
    r6_adj = r6 / ann_vol
    score = 0.55 * _zscore(mom_adj) + 0.30 * _zscore(resid_adj) + 0.15 * _zscore(r6_adj)
    score = score - 0.05 * _zscore(ann_vol)

    valid_sig = valid & last_sig.notna() & np.isfinite(last_sig) & score.notna() & np.isfinite(score) & vol60.notna() & (vol60 > 0)
    if valid_sig.sum() < 6:
        alt = mom.where(valid & mom.notna())
        if alt.notna().sum() < 6:
            return zero
        score = _zscore(alt)
        valid_sig = alt.notna() & np.isfinite(score)

    s = score[valid_sig].replace([np.inf, -np.inf], np.nan).dropna()
    if len(s) < 4:
        return zero

    n_side = min(25, len(s) // 2)
    if n_side < 1:
        return zero
    ordered = s.sort_values(ascending=False)
    longs = ordered.index[:n_side]
    shorts = ordered.index[-n_side:]

    if len(mkt.dropna()) >= 60:
        mvol = float(mkt.tail(60).std(ddof=0) * math.sqrt(252.0))
    else:
        mvol = 0.20
    if not np.isfinite(mvol) or mvol <= 0:
        mvol = 0.20
    scale = min(1.0, max(0.35, 0.20 / mvol))
    side_gross = 0.5 * scale
    w = min(0.02, side_gross / float(n_side))

    weights = pd.Series(0.0, index=tickers, dtype=float)
    weights.loc[longs] = w
    weights.loc[shorts] = -w

    net = weights.sum()
    if abs(net) > 1e-12:
        nz = weights.index[weights != 0.0]
        if len(nz) > 0:
            weights.loc[nz] -= net / len(nz)

    weights = weights.replace([np.inf, -np.inf], 0.0).fillna(0.0).clip(-0.02, 0.02)
    gross = weights.abs().sum()
    if gross > 1.0:
        weights = weights * (1.0 / gross)
    net = weights.sum()
    if abs(net) > 1e-12:
        nz = weights.index[weights != 0.0]
        if len(nz) > 0:
            weights.loc[nz] -= net / len(nz)
    return weights.clip(-0.02, 0.02).fillna(0.0).astype(float)

import numpy as np
import pandas as pd

def generate_weights(history, universe):
    tickers = pd.Index(list(universe))
    n = len(tickers)
    if n == 0:
        return pd.Series(dtype=float)
    zero = pd.Series(np.zeros(n, dtype=float), index=tickers)
    ac = history.get('adjusted_close')
    if ac is None or len(ac.index) < 5:
        return zero
    try:
        ac = ac.reindex(columns=tickers)
    except Exception:
        return zero
    dates = ac.index
    last_pos = len(dates) - 1
    signal_pos = last_pos
    if isinstance(dates, pd.DatetimeIndex) and last_pos >= 0:
        wd = dates.weekday.values
        mons = np.where(wd[:last_pos + 1] == 0)[0]
        if len(mons) > 0:
            signal_pos = mons[-1]
    L = 21
    if signal_pos < L + 1:
        return zero
    close_all = ac.values
    cur_close = close_all[last_pos]
    valid = np.isfinite(cur_close) & (cur_close > 1.0)
    elig = history.get('eligible')
    if elig is not None:
        try:
            e = elig.reindex(index=dates, columns=tickers)
            le = e.iloc[last_pos].values
            if le.dtype == bool:
                valid_e = le
            else:
                valid_e = np.array([(x is True) or (x == 1) for x in le], dtype=bool)
            if np.any(pd.notna(le)):
                valid &= valid_e
        except Exception:
            pass
    close_sig = close_all[:signal_pos + 1]
    ret = close_sig[-1] / close_sig[-1 - L] - 1.0
    valid &= np.isfinite(ret)
    vol = history.get('volume')
    if vol is not None:
        try:
            v = vol.reindex(index=dates, columns=tickers).values[:signal_pos + 1]
            if v.shape[0] >= 20:
                dv = np.nanmean(close_sig[-20:] * v[-20:], axis=0)
                valid &= np.isfinite(dv) & (dv > 0)
                if valid.sum() >= 20:
                    thresh = np.nanpercentile(dv[valid], 20)
                    valid &= dv >= thresh
        except Exception:
            pass
    idx = np.where(valid)[0]
    if len(idx) < 6:
        return zero
    raw_score = -ret[idx]
    scores = raw_score.copy()
    try:
        if close_sig.shape[0] >= 22:
            daily = close_sig[-21:] / close_sig[-22:-1] - 1.0
            vol20 = np.nanstd(daily, axis=0)
            vol20 = np.where(np.isfinite(vol20) & (vol20 > 1e-8), vol20, np.nan)
            adj = raw_score / vol20[idx]
            ok = np.isfinite(adj)
            scores = np.where(ok, adj, raw_score)
    except Exception:
        scores = raw_score
    order = np.argsort(scores)
    m = min(25, len(idx) // 2)
    if m < 1:
        return zero
    long_sel = idx[order[-m:]]
    short_sel = idx[order[:m]]
    wt = min(0.02, 0.5 / m)
    w = np.zeros(n, dtype=float)
    w[long_sel] = wt
    w[short_sel] = -wt
    w = np.nan_to_num(w, nan=0.0, posinf=0.0, neginf=0.0)
    w = np.clip(w, -0.02, 0.02)
    return pd.Series(w, index=tickers)

import numpy as np
import pandas as pd
import math

def _rank_pct(s):
    s = pd.to_numeric(s, errors='coerce')
    s = s.replace([np.inf, -np.inf], np.nan)
    if s.notna().sum() < 2:
        return pd.Series(0.5, index=s.index)
    return s.rank(method='average', pct=True)

def generate_weights(history, universe):
    tickers = pd.Index(list(universe))
    weights = pd.Series(0.0, index=tickers, dtype=float)
    if len(tickers) == 0:
        return weights

    adj = history.get('adjusted_close')
    raw = history.get('close')
    vol_df = history.get('volume')
    elig_df = history.get('eligible')

    if adj is None:
        adj = raw
    if adj is None or adj.empty:
        return weights
    try:
        adj = adj.reindex(columns=tickers)
    except Exception:
        return weights

    if raw is None:
        raw = adj
    else:
        try:
            raw = raw.reindex(columns=tickers)
        except Exception:
            raw = adj

    dates = adj.index
    if len(dates) < 70:
        return weights

    current = dates[-1]
    try:
        month_start = pd.Timestamp(year=current.year, month=current.month, day=1)
    except Exception:
        month_start = current
    prior = dates[dates < month_start]
    if len(prior) > 0:
        signal_date = prior[-1]
    else:
        signal_date = dates[-1]

    p_all = adj.loc[:signal_date]
    p = p_all.tail(320)
    if len(p) < 70:
        return weights

    r_all = raw.loc[:signal_date]
    r = r_all.reindex(index=p.index, columns=tickers)

    v = None
    if vol_df is not None:
        try:
            v = vol_df.reindex(columns=tickers).loc[:signal_date].reindex(index=p.index)
        except Exception:
            v = None

    last_adj = pd.to_numeric(p.iloc[-1], errors='coerce').astype(float)
    if r is not None and len(r) > 0:
        last_raw = pd.to_numeric(r.iloc[-1], errors='coerce').astype(float)
    else:
        last_raw = last_adj

    valid = last_adj.notna() & np.isfinite(last_adj) & (last_adj > 0.0)
    valid = valid & last_raw.notna() & np.isfinite(last_raw) & (last_raw > 2.0)

    cnt = p.notna().sum()
    valid = valid & (cnt >= min(120, max(50, len(p) // 2)))

    if elig_df is not None:
        try:
            e = elig_df.reindex(columns=tickers).loc[:signal_date]
            if len(e) > 0:
                el = e.iloc[-1].fillna(False).astype(bool)
                valid = valid & el
        except Exception:
            pass

    rets = p / p.shift(1) - 1.0
    vol = rets.tail(120).std(ddof=0) * math.sqrt(252.0)
    vol = pd.to_numeric(vol, errors='coerce').replace([np.inf, -np.inf], np.nan)
    vol = vol.clip(lower=0.05, upper=2.0)
    valid = valid & vol.notna() & np.isfinite(vol) & (vol > 0.0)

    if len(p) > 253:
        r12 = p.iloc[-22] / p.iloc[-253] - 1.0
    elif len(p) > 127:
        r12 = p.iloc[-22] / p.iloc[-127] - 1.0
    else:
        r12 = pd.Series(np.nan, index=tickers)

    if len(p) > 127:
        r6 = p.iloc[-22] / p.iloc[-127] - 1.0
    elif len(p) > 64:
        r6 = p.iloc[-22] / p.iloc[-64] - 1.0
    else:
        r6 = pd.Series(np.nan, index=tickers)

    r12a = r12 / vol
    r6a = r6 / vol

    rank12 = _rank_pct(r12a).fillna(0.5)
    rank6 = _rank_pct(r6a).fillna(0.5)
    rankvol = _rank_pct(-vol).fillna(0.5)

    score = 0.55 * rank12 + 0.30 * rank6 + 0.15 * rankvol

    if v is not None:
        try:
            adv = (r * v).tail(60).median()
            adv = pd.to_numeric(adv, errors='coerce').replace([np.inf, -np.inf], np.nan)
            if (valid & adv.notna()).sum() >= 20:
                q = adv[valid & adv.notna()].quantile(0.2)
                thr = max(5e5, float(q) if np.isfinite(q) else 0.0)
                valid = valid & adv.notna() & (adv >= thr)
        except Exception:
            pass

    valid = valid & score.notna() & np.isfinite(score)

    if valid.sum() < 6:
        valid = last_adj.notna() & np.isfinite(last_adj) & (last_adj > 0.0)
        valid = valid & last_raw.notna() & np.isfinite(last_raw) & (last_raw > 2.0)
        valid = valid & score.notna() & np.isfinite(score)

    if valid.sum() < 4:
        return weights

    s = score[valid].dropna().sort_values()
    n_side = min(30, len(s) // 2)
    if n_side < 1:
        return weights

    w = min(0.02, 0.5 / float(n_side))
    longs = s.index[-n_side:]
    shorts = s.index[:n_side]

    weights.loc[longs] = w
    weights.loc[shorts] = -w
    weights = weights.replace([np.inf, -np.inf], 0.0).fillna(0.0).clip(-0.02, 0.02)
    return weights.astype(float)

import math
import numpy as np
import pandas as pd


def _get_df(history, key, tickers):
    df = history.get(key)
    if df is None:
        return None
    try:
        return df.reindex(columns=tickers)
    except Exception:
        return None


def generate_weights(history, universe):
    tickers = pd.Index(list(universe))
    if len(tickers) == 0:
        return pd.Series(dtype=float)

    zero = pd.Series(0.0, index=tickers, dtype=float)

    ac = _get_df(history, 'adjusted_close', tickers)
    if ac is None or ac.dropna(how='all').empty:
        ac = _get_df(history, 'close', tickers)
    if ac is None or ac.empty:
        return zero

    ac = ac.tail(420)
    if len(ac) < 80:
        return zero

    dates = ac.index
    last_pos = len(dates) - 1

    signal_pos = last_pos
    try:
        periods = dates.to_period('M')
        cur = periods[-1]
        prior = np.where(periods < cur)[0]
        if len(prior) > 0:
            signal_pos = int(prior[-1])
    except Exception:
        signal_pos = last_pos

    if signal_pos < 60:
        signal_pos = last_pos

    price = ac.iloc[:signal_pos + 1].astype(float)
    if len(price) < 80:
        return zero

    last_sig = price.iloc[-1]
    latest_price = ac.iloc[-1].astype(float)

    elig_df = _get_df(history, 'eligible', tickers)
    if elig_df is not None and len(elig_df) > 0:
        try:
            e = elig_df.reindex(index=ac.index).iloc[-1]
            e = e.fillna(False).astype(bool)
        except Exception:
            e = pd.Series(True, index=tickers)
    else:
        e = pd.Series(True, index=tickers)

    cnt = price.notna().sum()
    valid = (
        latest_price.notna() & np.isfinite(latest_price) & (latest_price > 2.0)
        & last_sig.notna() & np.isfinite(last_sig) & (last_sig > 2.0)
        & (cnt >= 80) & e
    )

    raw = _get_df(history, 'close', tickers)
    if raw is None:
        raw = ac
    raw_sig = raw.reindex(index=ac.index).iloc[:signal_pos + 1].astype(float)

    vol_df = _get_df(history, 'volume', tickers)
    if vol_df is not None:
        v = vol_df.reindex(index=ac.index).iloc[:signal_pos + 1].tail(21).astype(float)
        c = raw_sig.tail(21)
        adv = (v * c).median()
        adv_ok = adv.notna() & np.isfinite(adv) & (adv > 0)
        if adv_ok.sum() >= 20:
            thresh = max(250000.0, float(adv[adv_ok].quantile(0.20)))
            valid = valid & adv_ok & (adv >= thresh)

    rets = price.pct_change(fill_method=None)
    vol60 = rets.tail(60).std(ddof=0).replace([np.inf, -np.inf], np.nan)
    valid = valid & vol60.notna() & (vol60 > 0.005)

    def form(k):
        if len(price) > k:
            return price.iloc[-1] / price.iloc[-1 - k] - 1.0
        return pd.Series(np.nan, index=tickers)

    r5 = form(5)
    r21 = form(21)
    r252 = form(252)

    if len(price) >= 252:
        mom = price.iloc[-22] / price.iloc[-252] - 1.0
    elif len(price) >= 126:
        mom = price.iloc[-22] / price.iloc[-126] - 1.0
    else:
        mom = r252

    max21 = rets.tail(21).max()

    daily = rets.tail(260)
    mkt_ret = daily.mean(axis=1, skipna=True).dropna()
    if len(mkt_ret) >= 60:
        mkt_level = (1.0 + mkt_ret).cumprod()
        if len(mkt_level) >= 200:
            trend_up = bool(mkt_level.iloc[-1] > mkt_level.tail(200).mean())
        else:
            trend_up = bool(mkt_level.iloc[-1] > mkt_level.mean())
        mvol = float(mkt_ret.tail(60).std(ddof=0) * math.sqrt(252.0))
        roll_vol = mkt_ret.rolling(60).std(ddof=0) * math.sqrt(252.0)
        rv = roll_vol.dropna()
        if len(rv) > 20:
            high_vol = bool(mvol > float(rv.quantile(0.75)))
        else:
            high_vol = bool(mvol > 0.20)
    else:
        trend_up = True
        high_vol = False

    rev_score = (-r21 / (vol60 * math.sqrt(21.0))).replace([np.inf, -np.inf], np.nan)
    mom_score = (mom / (vol60 * math.sqrt(252.0))).replace([np.inf, -np.inf], np.nan)
    lowvol_score = (-vol60).replace([np.inf, -np.inf], np.nan)
    max_score = (-max21).replace([np.inf, -np.inf], np.nan)

    r_rev = rev_score.where(valid).rank(method='average', pct=True).fillna(0.5)
    r_mom = mom_score.where(valid).rank(method='average', pct=True).fillna(0.5)
    r_low = lowvol_score.where(valid).rank(method='average', pct=True).fillna(0.5)
    r_max = max_score.where(valid).rank(method='average', pct=True).fillna(0.5)

    if trend_up and not high_vol:
        score = 0.45 * r_rev + 0.30 * r_mom + 0.15 * r_low + 0.10 * r_max
        gross_target = 1.0
    else:
        score = 0.20 * r_rev + 0.10 * r_mom + 0.50 * r_low + 0.20 * r_max
        gross_target = 0.60 if high_vol else 0.80

    score = score.where(valid).replace([np.inf, -np.inf], np.nan).dropna()
    if len(score) < 10:
        return zero

    n_side = min(25, len(score) // 2)
    if n_side < 5:
        return zero

    ordered = score.sort_values()
    shorts = ordered.index[:n_side]
    longs = ordered.index[-n_side:]

    w = min(0.02, 0.5 / float(n_side)) * gross_target

    weights = zero.copy()
    weights.loc[longs] = w
    weights.loc[shorts] = -w

    weights = weights.replace([np.inf, -np.inf], 0.0).fillna(0.0).clip(-0.02, 0.02)
    gross = float(weights.abs().sum())
    if gross > 1.0:
        weights = weights * (1.0 / gross)

    return weights.astype(float)

import numpy as np
import pandas as pd
import math


def _get_df(history, names):
    for name in names:
        obj = history.get(name) if isinstance(history, dict) else None
        if isinstance(obj, pd.DataFrame):
            return obj
    return None


def _zscore(s):
    s = pd.to_numeric(s, errors='coerce').replace([np.inf, -np.inf], np.nan)
    if s.notna().sum() < 2:
        return pd.Series(0.0, index=s.index)
    mu = s.mean()
    sd = s.std()
    if not np.isfinite(sd) or sd < 1e-12:
        return pd.Series(0.0, index=s.index)
    return ((s - mu) / sd).fillna(0.0)


def generate_weights(history, universe):
    tickers = pd.Index(list(universe))
    zero = pd.Series(0.0, index=tickers, dtype=float)
    if len(tickers) == 0:
        return zero

    price = _get_df(history, ['adjusted_close', 'close'])
    if price is None:
        return zero
    try:
        price = price.reindex(columns=tickers).astype(float)
    except Exception:
        return zero
    if price.shape[0] < 80:
        return zero

    last_pos = price.shape[0] - 1
    block = 21
    signal_pos = (last_pos // block) * block
    if signal_pos < 60:
        return zero

    last_close = price.iloc[last_pos]
    valid = last_close.notna() & np.isfinite(last_close) & (last_close > 2.0)
    counts = price.iloc[:last_pos + 1].notna().sum()
    valid = valid & (counts >= 60)

    elig = _get_df(history, ['eligible'])
    if elig is not None and len(elig.index) > 0:
        try:
            e = elig.reindex(columns=tickers).iloc[-1]
            valid = valid & e.fillna(False).astype(bool)
        except Exception:
            pass

    vol_df = _get_df(history, ['volume'])
    raw_close = _get_df(history, ['close'])
    if vol_df is not None:
        try:
            v = vol_df.reindex(columns=tickers).iloc[-20:].astype(float)
            if raw_close is not None:
                c = raw_close.reindex(columns=tickers).iloc[-20:].astype(float)
            else:
                c = price.iloc[-20:].astype(float)
            adv = (v * c).median()
            valid = valid & adv.notna() & np.isfinite(adv) & (adv > 250000.0)
        except Exception:
            pass

    p = price.iloc[:signal_pos + 1]
    if p.shape[0] < 61:
        return zero
    last_sig = p.iloc[-1]
    rets = p.pct_change(fill_method=None)

    def lag_ret(lag):
        if p.shape[0] > lag:
            return p.iloc[-1] / p.iloc[-1 - lag] - 1.0
        return pd.Series(np.nan, index=tickers)

    def between_ret(recent_lag, old_lag):
        if p.shape[0] > old_lag:
            return p.iloc[-1 - recent_lag] / p.iloc[-1 - old_lag] - 1.0
        return pd.Series(np.nan, index=tickers)

    r6 = lag_ret(126)
    r12 = lag_ret(252)
    mom12 = between_ret(21, 252) if p.shape[0] > 252 else pd.Series(np.nan, index=tickers)
    mom6 = between_ret(21, 126) if p.shape[0] > 126 else pd.Series(np.nan, index=tickers)
    mom = mom12.copy()
    mom = mom.where(mom.notna(), mom6)
    mom = mom.where(mom.notna(), r12)
    mom = mom.where(mom.notna(), r6)

    vol60 = rets.tail(60).std(ddof=0)
    vol60 = vol60.replace([np.inf, -np.inf], np.nan).clip(lower=0.005)
    ann_vol = vol60 * math.sqrt(252.0)

    mkt = rets.mean(axis=1)
    win = min(120, max(20, rets.shape[0] - 1))
    R = rets.tail(win).to_numpy(dtype=float)
    M = mkt.tail(win).to_numpy(dtype=float)
    if R.size == 0:
        beta = pd.Series(1.0, index=tickers)
    else:
        mask = np.isfinite(R) & np.isfinite(M)[:, None]
        nobs = mask.sum(axis=0)
        Rv = np.where(mask, R, np.nan)
        Mv = np.where(mask, M[:, None], np.nan)
        with np.errstate(all='ignore'):
            mR = np.nanmean(Rv, axis=0)
            mM = np.nanmean(Mv, axis=0)
            cov = np.nansum((Rv - mR) * (Mv - mM), axis=0) / np.maximum(nobs - 1, 1)
            var = np.nansum((Mv - mM) ** 2, axis=0) / np.maximum(nobs - 1, 1)
            beta_vals = cov / var
        beta_vals = np.where(np.isfinite(beta_vals) & (nobs >= 40), beta_vals, 1.0)
        beta = pd.Series(beta_vals, index=tickers)

    if p.shape[0] > 252 and rets.shape[0] >= 252:
        mkt_cum = float(np.expm1(np.nansum(np.log1p(mkt.iloc[-252:-21].to_numpy(dtype=float)))))
        resid = mom12 - beta * mkt_cum
        resid = resid.where(resid.notna(), mom - beta * mkt_cum)
    elif p.shape[0] > 126 and rets.shape[0] >= 126:
        mkt_cum = float(np.expm1(np.nansum(np.log1p(mkt.iloc[-126:-21].to_numpy(dtype=float)))))
        resid = mom6 - beta * mkt_cum
        resid = resid.where(resid.notna(), mom - beta * mkt_cum)
    else:
        resid = mom

    mom_adj = mom / ann_vol
    resid_adj = resid / ann_vol
    r6_adj = r6 / ann_vol
    score = 0.55 * _zscore(mom_adj) + 0.30 * _zscore(resid_adj) + 0.15 * _zscore(r6_adj)
    score = score - 0.05 * _zscore(ann_vol)

    valid_sig = valid & last_sig.notna() & np.isfinite(last_sig) & score.notna() & np.isfinite(score) & vol60.notna() & (vol60 > 0)
    if valid_sig.sum() < 6:
        alt = mom.where(valid & mom.notna())
        if alt.notna().sum() < 6:
            return zero
        score = _zscore(alt)
        valid_sig = alt.notna() & np.isfinite(score)

    s = score[valid_sig].replace([np.inf, -np.inf], np.nan).dropna()
    if len(s) < 4:
        return zero

    n_side = min(25, len(s) // 2)
    if n_side < 1:
        return zero
    ordered = s.sort_values(ascending=False)
    longs = ordered.index[:n_side]
    shorts = ordered.index[-n_side:]

    if len(mkt.dropna()) >= 60:
        mvol = float(mkt.tail(60).std(ddof=0) * math.sqrt(252.0))
    else:
        mvol = 0.20
    if not np.isfinite(mvol) or mvol <= 0:
        mvol = 0.20
    scale = min(1.0, max(0.35, 0.20 / mvol))
    side_gross = 0.5 * scale
    w = min(0.02, side_gross / float(n_side))

    weights = pd.Series(0.0, index=tickers, dtype=float)
    weights.loc[longs] = w
    weights.loc[shorts] = -w

    net = weights.sum()
    if abs(net) > 1e-12:
        nz = weights.index[weights != 0.0]
        if len(nz) > 0:
            weights.loc[nz] -= net / len(nz)

    weights = weights.replace([np.inf, -np.inf], 0.0).fillna(0.0).clip(-0.02, 0.02)
    gross = weights.abs().sum()
    if gross > 1.0:
        weights = weights * (1.0 / gross)
